const $ = selector => document.querySelector(selector);

$("#register").addEventListener("click", () => {
  const errors = [];
  if ($("#email").value.trim() === "") errors.push("Email is required.");
  if ($("#password").value.length < 8) errors.push("Password must be at least 8 characters.");
  if (!$("#terms").checked) errors.push("You must accept the terms.");

  const list = $("#errors");
  list.innerHTML = "";
  for (const message of errors) {
    const li = document.createElement("li");
    li.textContent = message;
    list.appendChild(li);
  }
  $("#status").textContent = errors.length === 0 ? "Registered!" : "";
});

